    // Initial displacement at t=-dt: um1 = u0 - dt*v0 + 0.5*dt^2*a0
    Vector um1 = u0 - dt * v0 + 0.5 * dt * dt * a0;

    // Solve for u1 using the central difference formula:
    // u1 = 2*u0 - um1 - dt^2*M^{-1}*K*u0 = 2*u0 - um1 - dt^2*K*u0 (since M=I)
    Vector u1 = 2.0 * u0 - um1 - dt * dt * K * u0;

    // Store displacement history
    std::vector<Vector> displacements;
    displacements.reserve(nsteps + 1);

    // Step 0
    displacements.push_back(u0);

    // Time integration loop using explicit central difference:
    // u_{n+1} = 2*u_n - u_{n-1} - dt^2*M^{-1}*K*u_n
    // Since M=I: u_{n+1} = 2*u_n - u_{n-1} - dt^2*K*u_n
    Vector u_prev = u0;   // u_{n-1} for the first iteration will be u0
    Vector u_curr = u1;   // u_n for the first iteration will be u1
    Vector u_next(n);

    // We'll store every 10th step (0,10,20,...,100) -> 11 points
    std::vector<Vector> output_points;

    // Store step 0
    output_points.push_back(u0);

    // Integrate for nsteps steps
    // We need to compute from step 1 to step 100, storing steps 10,20,...,100
    // So we need to compute 100 steps total, but we already have u0 and u1
    // We'll compute u2 through u100 (99 more steps)
    for (int step = 1; step <= nsteps; ++step) {
        // For step 1: compute u2 using u0 and u1
        // u_{n+1} = 2*u_n - u_{n-1} - dt^2*K*u_n
        u_next = 2.0 * u_curr - u_prev - dt * dt * K * u_curr;

        // Update for next iteration
        u_prev = u_curr;
        u_curr = u_next;

        // Store every 10th step (including step 100)
        // Step 1 gives u2, step 2 gives u3, ..., step 10 gives u11, but we want u10, u20, etc.
        // Since we start from u0, we want the displacement at time step 10, 20, ..., 100
        // After step iterations, we have computed u_{step+1}
        // So after step=9, we have u10; after step=19, we have u20, etc.
        if (step % 10 == 0) {
            output_points.push_back(u_curr);
        }
    }

    // Output as JSON
    std::cout << "{\"test\":\"TRD1C\",\"timeseries\":[";

    for (size_t i = 0; i < output_points.size(); ++i) {
        if (i > 0) std::cout << ",";
        std::cout << "[";
        for (int j = 0; j < n; ++j) {
            if (j > 0) std::cout << ",";
            std::cout << std::scientific << std::setprecision(16) << output_points[i](j);
        }
        std::cout << "]";
    }

    std::cout << "]}" << std::endl;

    return 0;
}
